-- Generated from PDF text extraction; source text is stored in nodes.content.
-- PostgreSQL schema: one row per source PDF, nodes stored as JSONB.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY, title TEXT NOT NULL, original_title TEXT, document_type TEXT NOT NULL, year_bs INTEGER NOT NULL, year_ad INTEGER NOT NULL, total_pages INTEGER NOT NULL, nodes JSONB NOT NULL, source_filename TEXT NOT NULL
);

INSERT INTO legal_documents (id,title,original_title,document_type,year_bs,year_ad,total_pages,nodes,source_filename) VALUES ($CODEx589aa37d11$doc_the_privacy_act_2075_2018_2075_act_relating_to_individual_privacy$CODEx589aa37d11$,$CODExdb51596792$The Privacy Act, 2075 (2018)$CODExdb51596792$,NULL,$CODEx76f3b5a717$act$CODEx76f3b5a717$,2075,2018,19,$CODEx1337a80f09$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "www.lawcommission.gov.np\nThe Privacy Act, 2075 (2018)\nDate of Authentication\n2075.6.2 (18 September 2018)\nAct Number 14 of the year 2075 (2018)\nAn Act Made to Provide for Privacy\nPreamble:\nWhereas, it is expedient to make legal provisions on promoting dignified living\nstandards by making provisions to ensure the right to privacy of the matters relating to\nbody, residence, property, document, data, correspondence and character of every\nperson, to manage the protection and safe use of personal information remained in any\npublic body or institution, and to prevent encroachment on the privacy of every person;\nNow, therefore be it enacted by the Federal Parliament.", "children": []}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-1", "title": "Chapter-1", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short title and commencement: (1) This Act may be cited as the “Privacy Act,", "content": "2075 (2018).\"\n(2) This Act shall come into force immediately.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Definitions: Unless the subject or the context otherwise requires, in this Act,-", "content": "(a) \"Residence\" means a house, rented room, apartment, room or place\nof residence where any person resides, and this term also includes\na hotel, resort, lodge, guesthouse or camp room or any other place\nof similar nature where he or she stays to spend a night.\n(b) \"Prescribed\" or \"as prescribed\" means prescribed or as prescribed\nin the Rules framed under this Act.\n(c) \"Personal information\" means the following information related to\nany person:\n(1) His or her caste, ethnicity, birth, origin, religion, color or\nmarital status,\n(2) His or her education or academic qualification,\n(3) His or her address, telephone or address of electronic letter\n(email),\n1\nwww.lawcommission.gov.np\n(4) His or her passport, citizenship certificate, national identity\ncard number, driving license, voter identity card or details\nof identity card issued by a public body,\n(5) A letter sent or received by him or her to or from anybody\nmentioning personal information,\n(6) His or her thumb impressions, fingerprints, retina of eye,\nblood group or other biometric information,\n(7) His or her criminal background or description of the\nsentence imposed on him or her for a criminal offence or\nservice of the sentence,\n(8) Matter as to what opinion or view has been expressed by a\nperson who gives professional or expert opinion, in the\nprocess of any decision.\n(d) \"Property\" means a movable, immovable, physical or abstract,\ntangible or intangible property, and this term also includes\nintellectual property.\n(e) \"Public body\" means the following body:\n(1) The Government of Nepal, Provincial Government or Local\nLevel or government office under the Government of\nNepal, Provincial Government or Local Level,\n(2) A court, other judicial body, constitutional body or office\nthereunder,\n(3) A regulatory body or office thereunder,\n(4) A company, bank, committee having full or partial\nownership or control of the Government of Nepal,\nProvincial Government or Local Level or commission,\ncorporation, authority, incorporation, academy, board,\ncenter, council and other body corporate of similar nature\nestablished by the Government of Nepal, Provincial\nGovernment or Local Level pursuant to law.\n(5) A political party and organization registered under\nprevailing law,\n(6) A university, college, school, research center and other\nsimilar academic or educational institution that has been\n2\nwww.lawcommission.gov.np\nestablished or operated by the Government of Nepal,\nProvincial Government or Local Level or that has obtained\nfull or partial grants from the Government of Nepal,\nProvincial Government or Local Level.\n(7) An institution operated with credit, grant or guarantee of\nthe Government of Nepal, Provincial Government or Local\nLevel.\n(8) An institution having full or partial ownership or control of\nthe body mentioned in sub-clause (1), (2), (3) or (4).\n(9) Any other institution specified by the Government of Nepal\nas a public entity by publishing a notice in the Nepal\nGazette\n(f) \"Person holding public post\" means a person holding any post of a\npublic body upon being elected, nominated or appointed to such\npost.\n(g) \"Body corporate\" means an organization, company, bank,\ncommittee, cooperative association, federation or other body\ncorporate of similar nature established under the prevailing law.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-2", "title": "Chapter-2", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "3", "title": "Privacy of body and personal life of person: (1) The privacy of the matters", "content": "relating to physical and mental condition of every person shall be inviolable.\n(2) The matters of privacy of the body of any person shall be inviolable\nwithout the consent of the person concerned, except in cases of conducting his or\nher health examination, health treatment or emergency relief work.\n(3) Every person shall have the right to maintain the privacy of the\nmatters such as biological or biometric identity, gender identity, sexuality,\nsexual relation, conception or abortion, virginity, potency, impotency or physical\nillness related to his or her personal life.\n(4) No person shall publish, or cause to be published, any matters referred\nto in sub-section (3) which are related to any person so as to affect, inflict or\ninsult in the personal life of such a person, by writing, speaking, publishing or\nusing electronic means or any other manner.\n3\nwww.lawcommission.gov.np\n(5) Notwithstanding anything contained in this Section, the privacy of\nphysical or mental condition or private life of a person may be disclosed on the\nfollowing condition:\n(a) If it is a matter involving the consent of the person concerned,\n(b) If it is the matter already made public by the person concerned\nwith his or her own will,\n(c) If it is the matter investigated in the course of any offence, by the\ninvestigating or prosecuting official,\n(d) If the matter related to sub-section (3) or physical condition or\nprivate life of a person has to be disclosed for obtaining any\nfacility or concession, and he or she obtains or desires to obtain\nsuch facility or concession.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "To have family privacy: (1) Every person shall have the right to maintain", "content": "family privacy for maintaining the family life or the family integrity.\n(2) The matter related to mutual privacy that is known only between the\nhusband and wife in the course of conjugal life shall be inviolable except in the\ncases where it is necessary in the context of the case running between the\nhusband and wife.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Not to search body: (1) Without obtaining the consent of any person, his or her", "content": "body or anything with him or her or used by him or her shall not be searched.\n(2) Notwithstanding anything contained in sub-section (1), in cases where\nit is necessary to carry out any security check under the prevailing law or to\nsearch any person in the course of investigation of a criminal offence, the\nauthorized official or any person or security deputed for the purpose of security\nin accordance with his or her order may carry out search in accordance with law.\n(3) The officials deputed for conducting security check pursuant to sub-\nsection (2) shall have to retain with him or her the authority obtained for the\nsecurity check, and show it before conducting search if the person concerned\nwants to see it.\n(4) The security person deputed to follow the duty for regular or\nemergency security check at any public place, wearing the badge and uniform\naccording to his or her post, shall be deemed to have had the authority for the\nsecurity check.\n4\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Privacy relating to reproductive health and pregnancy: The matter relating to", "content": "reproductive health and pregnancy of every woman shall be inviolable and,\nwithout her consent, information of such matter shall not be given to anyone else\nor be made public.\nProvided that, it shall not bar to hold discussion between the concerned\nspecialists about such matter in the course of health treatment or providing\ninformation for the member of his or her undivided family and for his or her\nguardian, if he or she has not attained the age of eighteen years or is of unsound\nmind.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-3", "title": "Chapter-3", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "7", "title": "To have privacy of residence: (1) Every person shall have the right to privacy", "content": "of his or her residence.\n(2) Except for searching under the law by the authorized official or in\naccordance with his or her order, entering, or causing other to enter into, the\nresidence of any person, or searching or getting it searched shall be forbidden.\n(3) While entering pursuant to sub-section (2), entering or causing other\nto enter into, or searching or getting it searched, by breaching the privacy of the\npersonal life of the person concerned or member of his or her family, shall be\nforbidden.\n(4) When any person is arrested outside his or her residence by the\nauthorized official or pursuant to order of such official, searching or causing his\nor her residence to be searched, simply because he is arrested, shall be forbidden.\n(5) If there is a reasonable cause to search his or her residence as well\nwhen any person is arrested pursuant to sub-section (4), his or her residence may\nbe searched for that purpose by obtaining a separate order of the authorized\nofficial pursuant to law.\n(6) Notwithstanding anything contained elsewhere in this Section, for the\npurpose of carrying out disaster management or emergency rescue, any person's\nresidence may be entered into.\n(7) Other provisions relating to maintaining privacy of the residence and\nsearch or investigation shall be in accordance with the prevailing law.\n5\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "To provide notice while entering into residence: (1) If anybody's residence is", "content": "to be searched pursuant to Section 7 in the course of any criminal offence, he or\nshe shall have to be provided with a written notice setting out the purpose for so\nentering into the residence thereof.\n(2) The conditions and procedures under the prevailing law shall have to\nbe fulfilled while entering into the residence of any person pursuant to sub-\nsection (1).\nProvided that if the accused person is likely to flee or escape or evidence\nis likely to be destroyed if search is not conducted immediately, it may be\nentered into by maintaining the record of such matter.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "Not to install CCTV camera in the residence: No person shall install, or cause", "content": "to be installed, CCTV camera at the residence of any person without his or her\nconsent, or for collecting personal information related to the user of such\nresidence.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-4", "title": "Chapter-4", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "10", "title": "To have privacy of property: (1) Every person shall have the right to keep his", "content": "or her property and details relating to such property confidential.\n(2) No person shall enter, in an unauthorized manner, into other's house,\nland, vehicle or other property without permission or consent of the owner of\nsuch property.\n(3) The public body or body corporate or any employee working in such a\nbody that keeps the details relating to the property of a person or that can have\ninformation thereof shall not inform anyone else, or publish or cause the details\nof property of any person published in any way, without the consent of the\nconcerned person.\n(4) Notwithstanding anything contained in sub-section (1) or (3), when\nthe details of property is demanded in accordance with the order of authorized\nofficial in the course of investigation of any offence, or when demand is made by\nthe court in the context of the case filed against any person on the same issue,\nthe concerned agency, body corporate or official that maintains the records of the\ndetails of property shall provide such record.\n6\nwww.lawcommission.gov.np", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-5", "title": "Chapter-5", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "11", "title": "To have privacy of document: (1) Every person shall have the right to privacy", "content": "of the personal document related to him or her.\n(2) For the purpose of sub-section (1), the following documents shall be\ndeemed to be the personal documents of the concerned person:\n(a) Certificate relating to educational qualification,\n(b) Medical history, certificate or health examination report,\n(c) Citizenship certificate, passport, voter identity card, driving\nlicense or other documents of such nature revealing identity,\n(d) Bank account in a bank or the details of amount in such account,\n(e) Cheque, draft, debit card, credit card or bank statement or other\nnegotiable instrument related to banking and financial transaction,\n(f) Biological or biometric data and thumb impression,\n(g) Land ownership certificate related to immovable property or other\ndocument relating to ownership of land,\n(h) Vehicle ownership card (Blue Book) or document relating to the\nownership of other property,\n(i) Securities or details related thereto,\n(j) Identity card of the Employee Provident Fund, pension card or\nother document of similar nature,\n(k) Other documents as prescribed.\n(3) No person shall publish, or cause to be published, personal\ndocument of anyone held in a public body pursuant to sub-section (2).\n(4) Notwithstanding anything contained in sub-section (1) or (3), personal\ndocument or any of its details may be published, or caused to be published, or\nany details thereof may be made subject of study, research or examination on the\nfollowing conditions:\n(a) If there is consent of the concerned person,\n(b) If the identity card revealing the identity of any person is required\nfor the purpose of using public service,\n(c) If order is issued under the law by the court or authorized official\nin the course of any case,\n7\nwww.lawcommission.gov.np\n(d) If any order is so issued by the authorized official in the course of\ninvestigation and prosecution of a criminal offence.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-6", "title": "Chapter-6", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "12", "title": "To have privacy of data: (1) Every person shall have the right to keep the", "content": "personal data or details related to him or her confidential.\n(2) While collecting personal or family data of any person, his or her\nconsent shall be obtained.\n(3) The data collected by a public body or body corporate upon\nobtaining the consent of the concerned person shall be used only for the purpose\nfor which such data have been collected.\nProvided that if any data are demanded for the national security or peace\nand order, it shall not be deemed to bar to provide such data in accordance with\nthe prevailing law.\n(4) No person shall, without obtaining the consent of another person,\nprovide the following data related to that person to anyone else or publish, or\ncause to be published, such data:\n(a) Details relating to health examination,\n(b) Details relating to property and income generation,\n(c) Details relating to employment,\n(d) Details relating to family matters,\n(e) Biometric details and thumb impression,\n(f) Signature or electronic signature,\n(g) Details relating to political affiliation and election,\n(h) Details relating to business or transaction.\n(5) Notwithstanding anything contained in sub-section (4), in cases\nwhere it is necessary to provide any personal data or details to the court or the\nagency or official authorized under law in the course of investigation of any\ncriminal offence, such data or details shall be provided.\n(6) Notwithstanding anything contained in sub-section (4), if there\narises a question as to the issues such as age, qualification, character, sexuality,\ndisability of any person, and the authorized official so demands, the concerned\nperson shall provide such details or documents.\n8\nwww.lawcommission.gov.np", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-7", "title": "Chapter-7", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "13", "title": "To have privacy of correspondence: (1) Every person shall have the right to", "content": "maintain privacy of his or her letters, correspondence or electronic letters\n(emails) or the dialogue transmitted through electronic means or other\ncorrespondence of similar nature.\n(2) No person shall, in an unauthorized manner, read, see, provide to\nanyone else, publish, broadcast, or otherwise make public the letters,\ncorrespondence or electronic letters (emails) or dialogue transmitted by\nelectronic means or other correspondence of similar nature referred to in sub-\nsection (1).\n(3) Notwithstanding anything contained in sub-section (2), the letters,\ncorrespondence or electronic letters (emails) or dialogue to be transmitted\nthrough electronic means or other correspondence of similar nature may be\nprovided, or cause to be provided with the consent of the concerned person or by\nthe order of the authorized official in the course of the investigation of any\ncriminal offence.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "14", "title": "Not to open letters: (1) Except with the consent of the person concerned, or the", "content": "order issued under the prevailing law by any competent authority in the course of\nthe investigation of any criminal offence, no one shall open, or cause to be\nopened, personal letters of such person.\n(2) No person shall open, see or forward the electronic letters (emails)\nof other person.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-8", "title": "Chapter-8", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "15", "title": "To have privacy of character: (1) Every person shall have the right to maintain", "content": "privacy of his or her character, personal conduct and behavior.\n(2) Except in the case of taking action under law by inquiring into any\nquestion that is raised regarding the character, conduct or behavior of any\nperson, no person shall make any comments on the character of that person.\n(3) No person shall do any kind of act or action so as to affect the\ncharacter of any person, defame or insult him or her, harm his or her self-esteem\n9\nwww.lawcommission.gov.np\nor affect in his or her family life, or publish, or cause to be published, any matter\nrelating to his or her conduct or behavior.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "16", "title": "Not to take or sell photograph: (1) No person shall take photograph of any", "content": "person without his or her consent so as to damage his or her character or social\nprestige, or make another picture by putting picture of other person together with\nhis or her picture by any way with the intention to defame him or her or to make\nanother picture by mixing some part of the picture of one person with another\npart of the picture of another person, or publish or cause to be published or made\npublic the same.\n(2) Notwithstanding anything contained in sub-section (1), if the\npicture of another person in the same place also happens to be taken by anybody\nwhile taking the picture of any public place or any person, it shall not be deemed\nto be the offence.\nProvided that the picture happened to be so taken also shall not be used is\ncontrary to sub-section (1).\n(3) No person shall publish, disseminate, buy, sell or publish the\npicture of any person that has been taken without obtaining his or her consent\nwith the intention to annoy, distress or take any improper advantage or get profit\nby making commercial use of the picture, or cause such act to be done.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "17", "title": "Not to make the person under investigation public: Until the charge sheet has", "content": "been filed in the concerned body regarding the offence of which any person\nunder investigation in accordance with the law has been accused, the authorized\nofficial shall not make him or her public in any manner.\nProvided that it shall not bar to publish the name of such accused person\nand detail or information of the charge against him or her.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "18", "title": "Not to disclose confidential matter: If any person has obtained any matter", "content": "relating to the conduct of anyone from any other person in the course of his or\nher professional duty, that person shall not disclose such matter to anyone except\nwhere the concerned person has so consented or order has been made by the\nauthorized official to that effect.\n10\nwww.lawcommission.gov.np", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-9", "title": "Chapter-9", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "19", "title": "To have privacy of electronic means: (1) Every person shall have the right to", "content": "maintain privacy of the matter relating to any of his or her personal information,\ndocument, correspondence, data or character that remained in electronic means.\n(2) No one shall obtain the notice, information, correspondence of any\nperson remained in electronic means in unauthorized manner, violate or provide\nits privacy for anybody in unauthorized manner.\n(3) Except for the consent given by the concerned person or order\nissued, under law, by authorized official, no one shall listen to any dialogue or\ntalks held between two or more than two persons through electronic means, or\nmark or record the sound of such talks by making use of any mechanical device.\nProvided that in the case of a speech or statement made publicly, the\nprovision of this sub-section shall not be applicable.\n(4) Notwithstanding anything contained in sub-section (2) or (3), any\nnotice, information or correspondence may be listened to, marked or recorded, or\ncause to be listened to, marked or recorded with the consent of the concerned\nperson or order of the authorized official.\n(5) Other provisions relating to the privacy of electronic notice and\ndata shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "20", "title": "Relating to installing CCTV camera at public place: (1) If it is necessary to", "content": "install CCTV camera at any public place, such camera may be installed, or\ncaused to be installed, at a place other than the toilet, bathroom or changing\nroom.\n(2) Provision shall be made to give a notice of such camera installed at\nthe place where the camera has been installed pursuant to sub-section (1) so that\nall can see and be informed.\n(3) The provisions relating to the installation of the CCTV camera at any\nplace shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "21", "title": "Not to make surveillance or espionage: In order to make surveillance or", "content": "espionage of the residence of any person or any office, or for the purpose of\nobtaining anything confidential pursuant to this Act, no electronic means,\nphotography or method may be used.\n11\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "22", "title": "Not to use drone: No drone of any kind or similar kind of other device shall be", "content": "used or no act shall be done with the purpose of obtaining any secret information\nof any public body, archaeologically important place, building of security\nagency, protected zone or zone of mine or mineral or at the residence of any\nperson, without permission of the authorized official or such a person, except in\nborder area or public place of the country.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-10", "title": "Chapter-10", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "23", "title": "Not to collect personal information except in accordance with law: (1) No", "content": "one except the official authorized under law or the person permitted by such\nofficial shall collect, store, protect, analyze, process or publish the personal\ninformation of any person.\n(2) Notwithstanding anything contained in sub-section (1), information\nprovided by the concerned person may be collected after obtaining his or her\nconsent for the purpose of conducting any study, research or collection of public\nopinion.\n(3) While collecting information pursuant to sub-section (2), it shall not\nbe collected without fully informing him or her regarding the purpose for which\nthe information is collected.\nExplanation: When the notice about collecting data is broadcast or\npublished through the media of mass communication by addressing the general\npublic, such notice shall be deemed to have provided information for the\npurposes of this Section.\n(4) While collecting information pursuant to sub-section (2), the\nfollowing matters shall be clearly set out:\n(a) Time of collecting information,\n(b) Content of information,\n(c) Nature of information,\n(d) Objective of collecting information,\n(e) Method and process of testing information,\n(f) Certainty of the matter of maintaining privacy of the collected\ninformation,\n(g) Matters including the protection of the collected information.\n12\nwww.lawcommission.gov.np\n(5) While collecting information of any person, the official authorized for\ncollecting information pursuant to law shall have to collect it by obtaining\ninformation from the concerned person.\n(6) Notwithstanding anything contained in sub-section (5), the following\nperson may provide the information on behalf of the following person:\n(a) In the case of the person who has not attained to the age of\neighteen years or who is of unsound mind, his or her guardian or\ncurator, provided there will be no harm to him or her when such\ninformation is so provided.\n(b) In the case of the other person, the attorney or representative\nauthorized by him or her.\n(7) Except in the following circumstance, the official authorized pursuant\nto sub-section (1) shall not collect personal information:\n(a) If the personal information has been collected by such official\nusing authority under the same law under which it is collected,\n(b) If there is provision for collecting such information by such\nofficial under the prevailing law,\n(c) If it is collected in the course of investigation, prosecution of\ncriminal offence or action under the court proceeding or\nenforcement of law,\n(d) If the person regarding whom any body corporate or public body\ncollects information, holds or is about to hold any post of such a\nbody, or if such information remain under the approved programs\nof such a body corporate or body.\n(8) Other provisions relating to the collection, processing, analysis and\nuse of personal information shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "24", "title": "Not to deem to be personal information: Except as otherwise provided in the", "content": "prevailing law, the following information regarding the person holding a public\npost shall not be deemed to be his or her personal information:\n(a) The matter as to of which public body he or she is an incumbent\nofficial,\n(b) His or her post and office address, telephone number or address of\nelectronic letter (email) through which contact may be established,\n13\nwww.lawcommission.gov.np\n(c) Name of the person signing any letter or document issued or\nwritten by a public body, and his or her post,\n(d) Description of job to be performed by him or her and its nature,\n(e) Matters relating to the conditions of his or her service.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "25", "title": "Protection of collected information: (1) The personal information that has been", "content": "collected by any public body or remained under the responsibility or control of\nsuch a body shall be protected by such body.\n(2) For the purpose of sub-section (1), the public body shall have to make\nappropriate arrangement against unauthorized access likely to occur to personal\ninformation, or against the possible risk of unauthorized use, change, disclosure,\npublication or transmission of such information.\n(3) Notwithstanding anything contained elsewhere in this Section, the\npublic body may disclose or get any personal information disclosed under the\nprevailing law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "26", "title": "Not to use personal information without consent: (1) Except in the following", "content": "circumstances, the personal information collected by or remained under the\nresponsibility or control of a public body or body corporate shall not be used or\ngiven to any one without the consent of the concerned person:\n(a) It has been published or distributed for the purpose of which the\npersonal information has been collected,\n(b) If demanded in written form, in the course of investigation or\nprosecution of a criminal case, by the official authorized for\nmaking such investigation or prosecution,\n(c) If an order is made by the court in the course of taking action on a\nsub-judice case,\n(d) If question is to be solved, when it is raised about the qualification\nor any other matter of the person, who is holding a public post\nunder the prevailing law,\n(e) If the authorized official demands for any particular kind of\ninformation in written form, in order to solve the question raised\non any particular matter.\n(2) Notwithstanding anything contained in sub-section (1), the authorized\nofficial of the body having the responsibility for collection and protection of\ninformation may, in the following circumstances, publish, or cause to be\n14\nwww.lawcommission.gov.np\npublished, any personal information for the purpose of a study or investigation\nfor the public purpose:\n(a) If the matter about which investigation has been made cannot be\nfulfilled without personal identity,\n(b) If damage and loss is not caused to the concerned person while\ngiving personal information of any matter that has been given for\nthe purpose of investigation,\n(c) If the concerned person has consented at the time of obtaining\ninformation or any time thereafter for the public purpose.\n(3) Notwithstanding anything contained in this Section, for the purpose of\narchives officially established by the Government of Nepal or Provincial\nGovernment, personal information may be provided, in the following\ncircumstances:\n(a) If there is any information that does not affect negatively to the\npersonal status, professional or personal privacy of the concerned\nperson,\n(b) If such information is provided for the historical research or\ncollection or accumulation of historical facts or information,\n(c) If it is personal information of any person thirty years or more than\nthirty years has passed after the death of such person.\nProvided that such information shall not be provided if he\nor she gets insulted or it causes damage and loss or insultation in\nany manner to his or her heir or children, as a result of the\npublicity of personal information of such person.\n(d) If such information has been recorded since one hundred years or\nmore than that period.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "27", "title": "Not to process sensitive information: (1) A public body shall not process, or", "content": "cause to be processed, any sensitive personal information remained under its\nresponsibility or control.\n(2) For the purposes of sub-section (1), the following information shall be\ndeemed to be sensitive information of the concerned person:\n(a) His or her caste, ethnicity or origin,\n(b) Political affiliation,\n(c) Religious faith or belief,\n15\nwww.lawcommission.gov.np\n(d) Physical or mental health or condition,\n(e) Sexual orientation or event relating to sexual life,\n(f) Details relating to property.\n(3) Notwithstanding anything contained in sub-section (2), such\ninformation may be processed in the following circumstances:\n(a) In the course of alleviation of disease, public health protection,\ndisease identification, health treatment, management of health\ninstitution and providing health service by the licensed doctor in\nthe concerned subject or by the health worker under direction of\nthe licensed doctor, without insulting or letting the concerned\nperson feel inferior.\n(b) If the concerned person has published the information himself or\nherself.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "28", "title": "Application may be made to correct information: (1) If any person thinks that", "content": "any information related to him or her which is remained under the responsibility,\nprotection or control of any public body is wrong or is not based on the fact, he\nor she may, at any time, make an application to the concerned public body in the\nprescribed form to correct such information.\nProvided that if he or she has already taken any advantage or facility on\nthe basis of such information, application may not be made to correct such\ninformation.\n(2) While making an application pursuant to sub-section (1), he or she\nshall have to submit the details of why such information has been wrong or has\nnot been based on the fact, and also the evidence to justify the fact or details\nclaimed by him or her.\n(3) If an application is made pursuant to sub-section (1) and the public\nbody thinks that it is necessary to correct such information as prescribed by\nmaking inquiry, it may correct such information by making necessary\nimprovement.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-11", "title": "Chapter-11", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "29", "title": "Offence and punishment: (1) If a person does, or causes to be done, any of the", "content": "following acts, he or she shall be deemed to have committed the offence under\nthis Act:\n16\nwww.lawcommission.gov.np\n(a) Any act contrary to sub-sections (1), (2) and (4) of Section 3,\n(b) Any act contrary to sub-section (2) of Section 4,\n(c) Any act contrary to sub-section (1) of Section 5,\n(d) Any act contrary to Section 6,\n(e) Act contrary to Sub-section (2), (3) and (4) of Section 7,\n(f) Any act contrary to Section 9,\n(g) Any act contrary to sub-section (2) and (3) of Section 10,\n(h) Any act contrary to sub-section (3) of Section 11,\n(i) Any act contrary to sub-section (4) of Section 12,\n(j) Any act contrary to sub-section (2) of Section 13,\n(k) Any act contrary to Section 14,\n(l) Any act contrary to sub-sections (2) and (3) of Section 15,\n(m) Any act contrary to Section 16,\n(n) Any act contrary to Section 18,\n(o) Any act contrary to sub-sections (2) and (3) of Section 19,\n(p) Any act contrary to Section 21,\n(q) Any act contrary to Section 22,\n(r) Any act contrary to sub-sections (1), (3) and (7) of Section 23,\n(s) Any act contrary to sub-section (1) of Section 26,\n(t) Any act contrary to sub-section (1) of Section 27,\n(2) Punishment of imprisonment for a term not exceeding three years\nor fine not exceeding thirty thousand rupees or both shall be imposed for the\noffence referred to in sub-section (1),\n(3) The Government of Nepal shall become the plaintiff in the cases on\nthe offences as referred to in clause (c), (m), (p), (q), (r), (s) or (t), and such\noffences shall be deemed to have been included in Schedule-1 of the National\nCriminal Procedure Code, 2074.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "30", "title": "Complaint may be made: (1) When any offence under this Act, other than that", "content": "mentioned in sub-section (3) of Section 29, is committed, the concerned person\nmay make a complaint to the concerned District Court.\n(2) While making a complaint pursuant to sub-section (1), it shall have to\nbe made within three months from the date of commission of such act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "31", "title": "Compensation: (1) If any kind of damage, loss or injury is caused to any person", "content": "due to the commission of any act deemed to be the offence or any other act under\n17\nwww.lawcommission.gov.np\nthis Act, the concerned person or victim may make a complaint to the concerned\nDistrict Court to get compensation paid for such damage, loss or pain, as well.\n(2) If a complaint referred to in sub-section (1) is made, the concerned\nDistrict Court shall cause to be paid the reasonable compensation to the victim\nfrom the offender if it thinks that compensation has to be paid.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "32", "title": "To award departmental punishment: If the person holding a public post does", "content": "not perform the act to be performed under this Act, or performs any act which is\nforbidden to be performed, the departmental or other punishment shall be\nawarded to him or her in accordance with the prevailing law relating to the\nconditions of his or her service, in addition to the punishment imposable\npursuant to this Act.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-12", "title": "Chapter-12", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "33", "title": "To obtain consent of guardian or curator: Notwithstanding anything contained", "content": "elsewhere in this Act, if the matters mentioned in this Act that they may be\npublished or privacy may be disclosed with the consent of the concerned person\nare related to the person who has not attained the age of eighteen years or who is\nof unsound mind or who has intellectual disability, such matters may be\npublished or privacy thereof be disclosed only when his or her guardian or\ncurator gives consent and if it benefits him or her while publishing such matters\nor disclosing privacy related to them.\n34 Not to deem to be a bar: (1) Nothing contained in this Act shall be deemed to\nbar the doing of the following in relation to the person mentioned in sub-section\n(2):\n(a) To obtain any notice or information in the course of court\nproceedings,\n(b) To obtain any personal information or details from any person,\nregarding investigation or prosecution of any offence under the\nlaw,\n(c) To publish his or her details relating to property under the\nprevailing law,\n(d) To publish by the body concerned, his or her details disclosing the\nidentity including educational qualification, citizenship, passport,\ndriving license,\n18\nwww.lawcommission.gov.np\n(e) Except for the matters prohibited by the prevailing law relating to\nthe press and newspapers and national broadcasting, to publish or\nbroadcast or make public any notice, information, data, news,\npicture obtained or collected in course of maintaining public\nwelfare and transparency or conducting investigative journalism,\nin any manner, without making it contrary to the basic norms of\nprivacy of the person,\n(f) To publish or transmit opinion, thoughts publicly expressed by him\nor her or audio-visual and picture captured in a publicly organized\nprogram,\n(g) To make fair comments, along with the basis, reason or evidence,\nabout the details related to his or her property or the details\nreferred to in clause (d) or the opinion, views expressed publicly\nby him or her or details related to his or her public function.\n(2) For the purposes of sub-section (1), the term \"person\" means the\nfollowing persons:\n(a) A person holding a public post,\n(b) A person involved in the formal process of being appointed,\nnominated or elected to a public post, or recommended for such a\npost,\n(c) A person retired from the service or relieved of a public post,\n(d) A person known publicly or who may be one of the public interest\nor concern,\n(e) A person who so appears that it is required to transmit a notice or\ninformation to the general public, owing to public welfare,\ndecency or morality or regarding the act that has been done or\nabout to be done against the law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "35", "title": "Not to act contrary to this Act: The body which transmits any public", "content": "information shall transmit such information in a manner not to be contrary to this\nAct.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "36", "title": "Power to frame Rules: The Government of Nepal may frame necessary Rules in", "content": "order to implement this Act.\n19", "children": []}]}]$CODEx1337a80f09$::jsonb,$CODEx1138cb094b$Act Relating to Individual Privacy, 2075.pdf$CODEx1138cb094b$) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, original_title=EXCLUDED.original_title, document_type=EXCLUDED.document_type, year_bs=EXCLUDED.year_bs, year_ad=EXCLUDED.year_ad, total_pages=EXCLUDED.total_pages, nodes=EXCLUDED.nodes, source_filename=EXCLUDED.source_filename;
